def weekly_allocations(modules):
    core = [m for m in modules if m['track'] == 'Основной маршрут']
    blocks = [(m['code'], m['hours']) for m in core if int(m['code']) <= 21]
    blocks += [('22',24), ('23',12), ('23',8), ('24',8), ('23',8), ('24',8), ('23',4), ('24',4)]
    weeks=[]; current=[]; filled=0
    for code,hours in blocks:
        remaining=hours
        while remaining:
            take=min(16-filled,remaining)
            if current and current[-1][0]==code:current[-1]=(code,current[-1][1]+take)
            else:current.append((code,take))
            remaining-=take;filled+=take
            if filled==16:weeks.append(current);current=[];filled=0
    if current:weeks.append(current)
    actual=Counter()
    for wk in weeks:
        for code,h in wk:actual[code]+=h
    assert actual==Counter({m['code']:m['hours'] for m in core})
    assert len(weeks)==len(WEEKS)==35
    assert sum(actual.values())==552
    assert weeks[31:]==[[('22',4),('23',12)],[('23',8),('24',8)],[('23',8),('24',8)],[('23',4),('24',4)]]
    return weeks

def add_execution_plan(b, api):
    modules=api['MODULES']; CW=api['CW']; TEAL=api['TEAL']; MUTED=api['MUTED']; PALE=api['PALE']; NAVY=api['NAVY']
    para=api['para']; e=api['e']; anchor=api['anchor']; MARGIN=api['MARGIN']
    allocations=weekly_allocations(modules)

    b.new('План выполнения: как двигаться','Календарь действий','execution')
    b.p('Рабочий вариант при 20 ч в неделю. Номер недели относительный: впиши дату старта после диагностики и необходимого повторения базы. Если доступен другой темп, пересчитай сроки по часам.',10.5,space=12)
    b.flow(['Неделя 0: диагностика','База по пробелам','Недели 1-31: реализация','Недели 32-35: пилот + защита'],'Пилот входит в 35 недель основного маршрута. Сроки сдвигаются, если не пройдена проверка готовности; углубления добавляются отдельно.')
    b.table([['Что планируем','Время и результат'],['Основной маршрут','552 ч занятий + 138 ч резерва = 690 ч. 34 недели по 20 ч и последняя до 10 ч.'],['Внутри обычной недели','16 ч: видео, чтение, реализация, проверка и журнал. 4 ч: исправления, повторение и непредвиденные трудности.'],['Диагностика, неделя 0','6-8 ч отдельно. Выбери нужные Б1-Б4; для полностью подтверждённой базы переходи к неделе 1.'],['Пилот, недели 32-35','32 ч модуля 23 в течение четырёх недель. 20 ч модуля 24 частично выполняются параллельно, без двойного учёта.']],[CW*.30,CW*.70],size=9.6)
    b.section('Одно изделие на всём пути','Веди один репозиторий и развивай одного AI-помощника. Каждый модуль добавляет функцию или доказательство надёжности. Отдельные эксперименты храни рядом, а не превращай каждый курс в новый незавершённый проект.')
    b.section('Три правила перехода','Есть работающий результат, сохранена существенная проверка отказа, ты можешь объяснить решение. Просмотр видео сам по себе не закрывает занятие. Если критерий не выполнен, используй резерв и пересчитай следующие недели.')
    b.p('Этот календарь раскладывает уже учтённые 552 часа: внедрение, review, лидерство и отчёт пилота не прибавляются второй раз. Часы - ориентир планирования, а не обещание сроков или трудоустройства.',9.5,color=MUTED,space=9)
    b.p(b.bookmark_link('execution_weeks_1','Открыть задания по неделям / '),10,markup=True)

    b.new('Первые шаги и ритм недели','От намерения к работе','execution_start')
    b.section('До недели 1: отдельные 6-8 часов','Выполни входную диагностику. Создай журнал времени, список пробелов и доску задач. Проверь доступ к учебным данным и контурам, выбери один процесс, назначь реальные окна занятий. Ошибки доступа исправь до подключения чужих данных.')
    b.table([['Сессия недели 1','Часы','Действие и результат'],['Пн','2','Выбрать процесс и пользователя. Описать текущие шаги и проблему.'],['Вт','2','Посмотреть и прочитать материалы 01. Записать вопросы к владельцу процесса.'],['Ср','2','Определить вход, выход, права, недопустимые действия и стоимость ошибки.'],['Чт','2','Проверить доступность 10 разрешённых примеров; описать ограничения данных.'],['Пт','2','Нарисовать архитектуру v1 и границы первой версии.'],['Сб','4','Собрать backlog и критерии результата; обсудить их с участником проекта.'],['Вс','2','Показать паспорт и схему, разобрать замечания, распланировать неделю 2.'],['Гибкое окно','4','Резерв: перенос, исправление, повторение. При отсутствии проблем отдых или углубление текущей темы.']],[CW*.22,CW*.09,CW*.69],size=9.3,pad=5)
    b.section('Неделя 2: та же сетка, новый результат','Распредели 16 ч между API, данными и правами из модуля 02. К выходным покажи загрузку документа, версию, статус задания и запрет чтения чужих данных. Остаток модуля 02 завершится на неделе 3.')
