            b.c.setFillColor(PALE);b.c.roundRect(MARGIN,b.y-hh,CW,hh,7,fill=1,stroke=0)
            yy=b.y-10
            for p,ph in rendered:p.drawOn(b.c,MARGIN+11,yy-ph);yy-=ph+4
