    b.section('Что делать при незакрытом пункте','Назови конкретный дефект и проверку, которая должна пройти. Возьми время из резерва; при нехватке сдвинь зависимые задачи. Независимую часть можно продолжить, но статус проблемного этапа остаётся открытым.')
    b.p(b.bookmark_link('pilot','Шаблон паспорта и отчёта пилота / ')+' · '+b.bookmark_link('failures','Сценарии отказов / '),9.3,markup=True)

